// Input Validation Node
const inputData = $input.first().json;
const requestData = inputData.body || inputData;

// Validate required structure
if (!requestData.candidates || !Array.isArray(requestData.candidates)) {
  throw new Error('candidates array is required');
}

if (requestData.candidates.length === 0) {
  throw new Error('candidates array cannot be empty');
}

// Validate each candidate record
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const validated = [];
const invalid = [];

for (const candidate of requestData.candidates) {
  // Check required fields
  if (!candidate.first_name || !candidate.last_name || !candidate.email) {
    invalid.push({
      candidate,
      reason: 'Missing required fields (first_name, last_name, email)'
    });
    continue;
  }

  // Validate email format
  if (!emailRegex.test(candidate.email)) {
    invalid.push({
      candidate,
      reason: 'Invalid email format'
    });
    continue;
  }

  // Valid candidate
  validated.push(candidate);
}

// Return validation results
return [{
  json: {
    valid_candidates: validated,
    invalid_candidates: invalid,
    valid_count: validated.length,
    invalid_count: invalid.length,
    total_uploaded: requestData.candidates.length,
    batch_id: requestData.upload_batch_id || `batch_${Date.now()}`,
    uploaded_by: requestData.uploaded_by || 'system',
    validation_timestamp: new Date().toISOString()
  }
}];

// Normalize Fields Function
const data = $input.first().json;
const candidates = data.valid_candidates;

function normalizePhone(phone) {
  if (!phone) return '';
  // Remove all non-numeric characters
  const cleaned = phone.replace(/[^0-9]/g, '');
  // Add +1 for US numbers if not present
  if (cleaned.length === 10) {
    return `+1${cleaned}`;
  }
  if (cleaned.length === 11 && cleaned.startsWith('1')) {
    return `+${cleaned}`;
  }
  return `+${cleaned}`;
}

function capitalizeName(name) {
  if (!name) return '';
  return name
    .toLowerCase()
    .split(' ')
    .map(word => word.charAt(0).toUpperCase() + word.slice(1))
    .join(' ')
    .trim();
}

function normalizeEmail(email) {
  if (!email) return '';
  return email.toLowerCase().trim();
}

// Normalize all candidates
const normalized = candidates.map(candidate => {
  return {
    ...candidate,
    first_name: capitalizeName(candidate.first_name),
    last_name: capitalizeName(candidate.last_name),
    full_name: `${capitalizeName(candidate.first_name)} ${capitalizeName(candidate.last_name)}`,
    email: normalizeEmail(candidate.email),
    phone: normalizePhone(candidate.phone),
    company: candidate.company ? candidate.company.trim() : '',
    job_title: candidate.job_title ? candidate.job_title.trim() : '',
    location: candidate.location ? candidate.location.trim() : '',
    normalized_at: new Date().toISOString()
  };
});

return [{
  json: {
    ...data,
    normalized_candidates: normalized,
    normalization_complete: true
  }
}];

// Fuzzy Matching Algorithm using Levenshtein Distance
const newCandidatesData = $input.item(0).json;
const existingCandidatesData = $input.item(1).json;

const newCandidates = newCandidatesData.normalized_candidates || [];
const existingCandidates = Array.isArray(existingCandidatesData) ? existingCandidatesData : [];

// Levenshtein distance algorithm
function levenshteinDistance(str1, str2) {
  const a = str1.toLowerCase();
  const b = str2.toLowerCase();
  const matrix = [];

  for (let i = 0; i <= a.length; i++) {
    matrix[i] = [i];
  }

  for (let j = 0; j <= b.length; j++) {
    matrix[0][j] = j;
  }

  for (let i = 1; i <= a.length; i++) {
    for (let j = 1; j <= b.length; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      matrix[i][j] = Math.min(
        matrix[i - 1][j] + 1,
        matrix[i][j - 1] + 1,
        matrix[i - 1][j - 1] + cost
      );
    }
  }

  return matrix[a.length][b.length];
}

// Calculate similarity percentage
function similarityScore(str1, str2) {
  if (!str1 || !str2) return 0;
  const maxLen = Math.max(str1.length, str2.length);
  if (maxLen === 0) return 100;
  const distance = levenshteinDistance(str1, str2);
  return ((maxLen - distance) / maxLen) * 100;
}

// Find duplicates
const results = [];
const SIMILARITY_THRESHOLD = 85;

for (const newCandidate of newCandidates) {
  let isDuplicate = false;
  let matchedRecord = null;
  let matchReason = '';

  for (const existing of existingCandidates) {
    // Rule 1: Exact email match
    if (newCandidate.email && existing.email &&
        newCandidate.email === existing.email) {
      isDuplicate = true;
      matchedRecord = existing;
      matchReason = 'exact_email_match';
      break;
    }

    // Rule 2: High name similarity + exact phone match
    const nameSimilarity = similarityScore(
      newCandidate.full_name,
      existing.full_name || `${existing.first_name} ${existing.last_name}`
    );

    if (nameSimilarity >= SIMILARITY_THRESHOLD &&
        newCandidate.phone && existing.phone &&
        newCandidate.phone === existing.phone) {
      isDuplicate = true;
      matchedRecord = existing;
      matchReason = `name_similarity_${nameSimilarity.toFixed(1)}%_phone_match`;
      break;
    }
  }

  results.push({
    candidate: newCandidate,
    isDuplicate: isDuplicate,
    matchedRecord: matchedRecord,
    matchReason: matchReason,
    processed_at: new Date().toISOString()
  });
}

// Return results with metadata
return [{
  json: {
    results: results,
    total_processed: results.length,
    duplicates_found: results.filter(r => r.isDuplicate).length,
    new_candidates: results.filter(r => !r.isDuplicate).length,
    batch_id: newCandidatesData.batch_id,
    matching_complete: true
  }
}];

// Split results into individual items for routing
const data = $input.first().json;
const results = data.results || [];

// Return each result as separate item
return results.map(result => ({
  json: {
    ...result.candidate,
    isDuplicate: result.isDuplicate,
    matchedRecord: result.matchedRecord,
    matchReason: result.matchReason,
    batch_id: data.batch_id
  }
}));

// Merge Records Function - Combine old and new data
const newData = $input.first().json;
const existingData = newData.matchedRecord || {};

// Merge strategy: Prefer newer non-null/non-empty values
function mergeValue(newVal, oldVal) {
  if (newVal !== null && newVal !== undefined && newVal !== '') {
    return newVal;
  }
  return oldVal;
}

const merged = {
  // Keep existing ID
  candidate_id: existingData.candidate_id,

  // Merge all fields
  first_name: mergeValue(newData.first_name, existingData.first_name),
  last_name: mergeValue(newData.last_name, existingData.last_name),
  full_name: mergeValue(newData.full_name, existingData.full_name),
  email: mergeValue(newData.email, existingData.email),
  phone: mergeValue(newData.phone, existingData.phone),
  company: mergeValue(newData.company, existingData.company),
  job_title: mergeValue(newData.job_title, existingData.job_title),
  resume_text: mergeValue(newData.resume_text, existingData.resume_text),
  linkedin_url: mergeValue(newData.linkedin_url, existingData.linkedin_url),
  years_experience: mergeValue(newData.years_experience, existingData.years_experience),
  location: mergeValue(newData.location, existingData.location),

  // Merge skills (combine unique values)
  skills: (() => {
    const newSkills = Array.isArray(newData.skills) ? newData.skills : 
                     (newData.skills ? newData.skills.split(',').map(s => s.trim()) : []);
    const oldSkills = Array.isArray(existingData.skills) ? existingData.skills :
                     (existingData.skills ? existingData.skills.split(',').map(s => s.trim()) : []);
    const combined = [...new Set([...newSkills, ...oldSkills])];
    return combined.filter(s => s).join(', ');
  })(),

  // Metadata
  source: newData.source,
  created_date: existingData.created_date,
  last_updated: new Date().toISOString(),
  update_source: 'deduplication_merge',
  match_reason: newData.matchReason,
  action: 'updated',
  batch_id: newData.batch_id
};

return [{ json: merged }];

// Parse NeverBounce response
const candidate = $input.first().json;
const response = candidate.result || {};

let emailStatus = 'unchecked';

if (response.result) {
  emailStatus = response.result; // 'valid', 'invalid', 'disposable', 'unknown'
}

return [{
  json: {
    ...candidate,
    email_status: emailStatus,
    email_checked_at: new Date().toISOString()
  }
}];

// Parse Clearbit company data
const candidate = $input.first().json;
const response = candidate || {};

let companyData = {};

if (response.name) {
  companyData = {
    company_size: response.metrics?.employees || null,
    company_industry: response.category?.industry || '',
    company_location: response.geo?.city || '',
    company_logo: response.logo || '',
    company_domain: response.domain || ''
  };
}

return [{
  json: {
    ...candidate,
    ...companyData,
    company_enriched: !!response.name
  }
}];

// Parse Proxycurl LinkedIn response
const candidate = $input.first().json;
const response = candidate.results || [];

let linkedinData = {
  linkedin_url: candidate.linkedin_url || '',
  profile_pic_url: ''
};

if (response.length > 0 && response[0].linkedin_profile_url) {
  linkedinData.linkedin_url = response[0].linkedin_profile_url;
  linkedinData.profile_pic_url = response[0].profile_pic_url || '';
}

return [{
  json: {
    ...candidate,
    ...linkedinData,
    linkedin_found: !!linkedinData.linkedin_url
  }
}];

// Parse GPT-4 skills extraction
const candidate = $input.first().json;
const gptResponse = candidate.message?.content || '';

let extractedSkills = '';

if (gptResponse) {
  // Clean up the response
  extractedSkills = gptResponse
    .split('\n')
    .filter(line => line.trim())
    .join(', ')
    .replace(/["\[\]]/g, '')
    .trim();
}

// Merge with existing skills if any
const existingSkills = candidate.skills || '';
const allSkills = [existingSkills, extractedSkills]
  .filter(s => s)
  .join(', ');

return [{
  json: {
    ...candidate,
    skills: allSkills,
    extracted_skills: extractedSkills,
    skills_extracted: !!extractedSkills
  }
}];

// Calculate Candidate Score
const candidate = $input.first().json;

let score = 0;

// COMPLETENESS (40 points)
if (candidate.email && candidate.email_status === 'valid') {
  score += 10;
} else if (candidate.email) {
  score += 5;
}

if (candidate.phone && candidate.phone.length > 5) {
  score += 5;
}

if (candidate.linkedin_url) {
  score += 10;
}

if (candidate.resume_text && candidate.resume_text.length > 100) {
  score += 10;
}

if (candidate.skills) {
  const skillCount = candidate.skills.split(',').filter(s => s.trim()).length;
  if (skillCount > 3) score += 5;
}

// EXPERIENCE (30 points)
const years = parseInt(candidate.years_experience) || 0;
if (years >= 5) {
  score += 30;
} else if (years >= 3) {
  score += 20;
} else if (years >= 1) {
  score += 10;
} else {
  score += 5; // Some credit for any experience data
}

// ENGAGEMENT (30 points)
if (candidate.company && candidate.company.length > 0) {
  score += 15;
}

if (candidate.location && candidate.location.length > 0) {
  score += 10;
}

if (candidate.source === 'referral') {
  score += 5;
}

// Ensure score is between 0-100
score = Math.min(100, Math.max(0, score));

// Assign tier
let tier = 'C';
if (score >= 80) {
  tier = 'A';
} else if (score >= 60) {
  tier = 'B';
}

return [{
  json: {
    ...candidate,
    candidate_score: score,
    candidate_tier: tier,
    score_calculated_at: new Date().toISOString()
  }
}];

// Assign to Recruiter based on tier and role
const candidate = $input.first().json;

const tier = candidate.candidate_tier || 'C';
const jobTitle = (candidate.standardized_title || candidate.job_title || '').toLowerCase();

// Engineering-related titles
const engineeringRoles = ['engineer', 'developer', 'devops', 'qa', 'architect'];
const isEngineering = engineeringRoles.some(role => jobTitle.includes(role));

// Recruiter assignment logic
let assignedRecruiter = '';
let assignmentReason = '';

if (tier === 'A' && isEngineering) {
  assignedRecruiter = 'senior-tech-recruiter@company.com';
  assignmentReason = 'tier_a_engineering';
} else if (tier === 'A' && !isEngineering) {
  assignedRecruiter = 'senior-general-recruiter@company.com';
  assignmentReason = 'tier_a_non_engineering';
} else if (tier === 'B') {
  // Round-robin assignment (simplified - use modulo of timestamp)
  const recruiters = [
    'mid-recruiter-1@company.com',
    'mid-recruiter-2@company.com',
    'mid-recruiter-3@company.com'
  ];
  const index = Date.now() % recruiters.length;
  assignedRecruiter = recruiters[index];
  assignmentReason = 'tier_b_round_robin';
} else {
  assignedRecruiter = 'junior-recruiter-pool@company.com';
  assignmentReason = 'tier_c_junior_pool';
}

return [{
  json: {
    ...candidate,
    assigned_recruiter: assignedRecruiter,
    assignment_reason: assignmentReason,
    assigned_at: new Date().toISOString()
  }
}];

// Tag for Campaigns - Segmentation Logic
const candidate = $input.first().json;

const tags = [];

// Tier-based tags
if (candidate.candidate_tier === 'A') {
  tags.push('high_priority');
} else if (candidate.candidate_tier === 'B') {
  tags.push('medium_priority');
}

// Experience-based tags
const years = parseInt(candidate.years_experience) || 0;
if (years >= 5) {
  tags.push('experienced');
} else if (years >= 2) {
  tags.push('mid_level');
} else if (years >= 0) {
  tags.push('junior');
}

// Skill-based tags
const skills = (candidate.skills || '').toLowerCase();
if (skills.includes('python')) tags.push('python_developer');
if (skills.includes('javascript') || skills.includes('react')) tags.push('frontend_developer');
if (skills.includes('aws') || skills.includes('azure')) tags.push('cloud_engineer');
if (skills.includes('sql') || skills.includes('database')) tags.push('data_specialist');

// Location-based tags
const location = (candidate.location || '').toLowerCase();
if (location.includes('remote')) tags.push('remote_candidate');
if (location.includes('san francisco') || location.includes('sf')) tags.push('bay_area');
if (location.includes('new york') || location.includes('nyc')) tags.push('new_york');

// Email validation tag
if (candidate.email_status === 'valid') {
  tags.push('verified_email');
}

// LinkedIn presence tag
if (candidate.linkedin_url) {
  tags.push('linkedin_profile');
}

return [{
  json: {
    ...candidate,
    campaign_tags: tags,
    tags_count: tags.length,
    tagged_at: new Date().toISOString()
  }
}];

// Aggregate all results for logging
const allItems = $input.all();

let totalUploaded = 0;
let duplicatesFound = 0;
let newCandidates = 0;
let tierACandidates = 0;
let tierBCandidates = 0;
let tierCCandidates = 0;
let emailsValidated = 0;
let linkedinFound = 0;
let skillsExtracted = 0;

for (const item of allItems) {
  totalUploaded++;

  if (item.json.action === 'updated') {
    duplicatesFound++;
  } else {
    newCandidates++;
  }

  if (item.json.candidate_tier === 'A') tierACandidates++;
  if (item.json.candidate_tier === 'B') tierBCandidates++;
  if (item.json.candidate_tier === 'C') tierCCandidates++;

  if (item.json.email_status === 'valid') emailsValidated++;
  if (item.json.linkedin_url) linkedinFound++;
  if (item.json.extracted_skills) skillsExtracted++;
}

const batchId = allItems[0]?.json?.batch_id || `batch_${Date.now()}`;
const uploadedBy = allItems[0]?.json?.uploaded_by || 'system';

return [{
  json: {
    timestamp: new Date().toISOString(),
    workflow: 'candidate-deduplication-enrichment',
    status: 'success',
    total_uploaded: totalUploaded,
    duplicates_found: duplicatesFound,
    new_candidates: newCandidates,
    tier_a_count: tierACandidates,
    tier_b_count: tierBCandidates,
    tier_c_count: tierCCandidates,
    emails_validated: emailsValidated,
    linkedin_found: linkedinFound,
    skills_extracted: skillsExtracted,
    uploaded_by: uploadedBy,
    batch_id: batchId,
    execution_time_ms: 0 // Will be calculated by n8n
  }
}];

// Format final response
const logData = $input.first().json;

const response = {
  success: true,
  message: `${logData.total_uploaded} uploaded, ${logData.duplicates_found} duplicates, ${logData.new_candidates} new`,
  details: {
    total_uploaded: logData.total_uploaded,
    duplicates_merged: logData.duplicates_found,
    new_candidates: logData.new_candidates,
    tier_breakdown: {
      A: logData.tier_a_count,
      B: logData.tier_b_count,
      C: logData.tier_c_count
    },
    enrichment_summary: {
      emails_validated: logData.emails_validated,
      linkedin_found: logData.linkedin_found,
      skills_extracted: logData.skills_extracted
    },
    batch_id: logData.batch_id,
    next_steps: 'Review Tier A candidates in ATS dashboard'
  },
  timestamp: logData.timestamp
};

return [{ json: response }];
